//! What the program sees of its images: `images.asm`, assembled with the
//! sources, which INCBINs each image's data under labels named after its
//! file, and `images.inc`, on the include path, with each image's sizes,
//! counts and palette as constants. Both are rewritten by every build.

use std::fmt::Write;

use gbcli_protocol::ImageKind;

use super::sheet::{Object, SheetPlan};

/// One converted image, as the generated files name it.
pub(crate) enum Entry<'a> {
    Bg {
        source: &'a str,
        label: &'a str,
        constant: &'a str,
        /// The data's path without extension, relative to the project.
        data: &'a str,
        width: u32,
        height: u32,
        tiles: u32,
    },
    Sheet {
        source: &'a str,
        label: &'a str,
        constant: &'a str,
        data: &'a str,
        plan: &'a SheetPlan,
    },
}

/// Every symbol an image of `kind` defines, from its label and constant
/// stems, but a sheet's `<Label>Frame<n>`: those end in the frame's number
/// after `Frame`, which no other symbol here does, so they can't collide
/// unless the labels do.
pub(crate) fn symbols(kind: ImageKind, label: &str, constant: &str) -> Vec<String> {
    let (labels, constants): (&[&str], &[&str]) = match kind {
        ImageKind::Bg => (
            &["Tiles", "TilesEnd", "Tilemap", "TilemapEnd"],
            &["WIDTH", "HEIGHT", "TILES", "BGP"],
        ),
        ImageKind::Sprites => (
            &["Tiles", "TilesEnd", "Frames"],
            &["TILES", "FRAMES", "FRAME_WIDTH", "FRAME_HEIGHT", "OBP"],
        ),
    };
    let labels = labels.iter().map(|s| format!("{label}{s}"));
    let constants = constants.iter().map(|s| format!("{constant}_{s}"));
    labels.chain(constants).collect()
}

const HEADER: &str = "; Generated by `gbcli build` from the images under assets/; every build \
rewrites it.\n; Edit the PNGs, not this file. Pan Docs: https://gbdev.io/pandocs/Graphics.html\n";

/// The assembly: one ROMX section per image.
pub(crate) fn asm(entries: &[Entry]) -> String {
    let mut out = String::from(HEADER);
    out += "; Constants: images.inc. Object attributes: $20 flips X, $40 flips Y.\n";
    for e in entries {
        match e {
            Entry::Bg {
                source,
                label,
                data,
                ..
            } => {
                let _ = write!(
                    out,
                    "\nSECTION \"image {label}\", ROMX\n\n\
                     ; {source}: unique tiles, then the map, a byte per tile, row by row.\n\
                     {label}Tiles::\n\tINCBIN \"{data}.2bpp\"\n{label}TilesEnd::\n\
                     {label}Tilemap::\n\tINCBIN \"{data}.tilemap\"\n{label}TilemapEnd::\n"
                );
            }
            Entry::Sheet {
                source,
                label,
                data,
                plan,
                ..
            } => {
                let _ = write!(
                    out,
                    "\nSECTION \"image {label}\", ROMX\n\n\
                     ; {source}: unique 8x16 objects, 32 bytes each (top tile, bottom tile).\n\
                     {label}Tiles::\n"
                );
                if plan.kept.is_empty() {
                    out += "\t; (no object: the sheet is transparent)\n";
                } else {
                    let _ = writeln!(out, "\tINCBIN \"{data}.2bpp\"");
                }
                let _ = write!(
                    out,
                    "{label}TilesEnd::\n\n\
                     ; One pointer per frame, left to right, then top to bottom. A frame is a\n\
                     ; count, then per object: y, x (pixels from the frame's top-left), tile\n\
                     ; (from {label}Tiles' first) and attributes.\n\
                     {label}Frames::\n"
                );
                let names: Vec<String> = (0..plan.frames.len())
                    .map(|i| format!("{label}Frame{i}"))
                    .collect();
                for chunk in names.chunks(8) {
                    let _ = writeln!(out, "\tdw {}", chunk.join(", "));
                }
                for (name, objects) in names.iter().zip(&plan.frames) {
                    let _ = write!(out, "{name}::\n\tdb {}\n", objects.len());
                    for o in objects {
                        out += &object(o);
                    }
                }
            }
        }
    }
    out
}

fn object(o: &Object) -> String {
    let flip = match o.flip {
        0 => "0".to_string(),
        f => format!("${f:02X}"),
    };
    format!("\tdb {}, {}, {}, {flip}\n", o.y, o.x, o.unit * 2)
}

/// The include: constants only, so any source may include it.
pub(crate) fn inc(entries: &[Entry]) -> String {
    let mut out = String::from(HEADER);
    out += "; Labels (in images.asm, exported): <Name>Tiles/<Name>TilesEnd, and\n\
            ; <Name>Tilemap/<Name>TilemapEnd for a background or <Name>Frames for a sheet.\n\
            \nIF !DEF(GBCLI_IMAGES_INC)\nDEF GBCLI_IMAGES_INC EQU 1\n";
    for e in entries {
        match e {
            Entry::Bg {
                source,
                constant: c,
                width,
                height,
                tiles,
                ..
            } => {
                let _ = write!(
                    out,
                    "\n; {source}: a background, {width}x{height} tiles.\n\
                     DEF {c}_WIDTH EQU {width} ; tiles per map row\n\
                     DEF {c}_HEIGHT EQU {height} ; map rows\n\
                     DEF {c}_TILES EQU {tiles} ; unique tiles, 16 bytes each\n\
                     DEF {c}_BGP EQU %11_10_01_00 ; each color index is its shade\n"
                );
            }
            Entry::Sheet {
                source,
                constant: c,
                plan,
                ..
            } => {
                let (fw, fh) = plan.frame;
                let obp = plan.obp;
                let _ = write!(
                    out,
                    "\n; {source}: 8x16 objects (set LCDC_OBJ_16), {} frame(s) of {fw}x{fh}.\n\
                     DEF {c}_TILES EQU {} ; tiles, two per object\n\
                     DEF {c}_FRAMES EQU {}\n\
                     DEF {c}_FRAME_WIDTH EQU {fw}\n\
                     DEF {c}_FRAME_HEIGHT EQU {fh}\n\
                     DEF {c}_OBP EQU %{:02b}_{:02b}_{:02b}_{:02b} ; shades of indices 3, 2, 1 \
                     (0 is transparent)\n",
                    plan.frames.len(),
                    plan.tiles(),
                    plan.frames.len(),
                    obp >> 6,
                    (obp >> 4) & 3,
                    (obp >> 2) & 3,
                    obp & 3,
                );
            }
        }
    }
    out += "\nENDC\n";
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The symbols the generated files define: exported labels in the
    /// assembly, constants in the include.
    fn defined(asm: &str, inc: &str) -> Vec<String> {
        let labels = asm.lines().filter_map(|l| l.strip_suffix("::"));
        let constants = inc
            .lines()
            .filter_map(|l| l.strip_prefix("DEF ")?.split_once(" EQU"))
            .map(|(name, _)| name)
            .filter(|&name| name != "GBCLI_IMAGES_INC");
        let mut all: Vec<String> = labels.chain(constants).map(str::to_string).collect();
        all.sort();
        all
    }

    #[test]
    fn symbols_lists_what_each_kind_defines_but_frame_labels() {
        let plan = SheetPlan {
            spec: String::new(),
            obp: 0,
            width: 1,
            height: 2,
            frame: (8, 16),
            kept: vec![(0, 0)],
            drawn: vec![vec![0; 128]],
            uses: vec![2],
            frames: vec![Vec::new(), Vec::new()],
            warnings: Vec::new(),
        };
        let entries = [
            Entry::Bg {
                source: "town.png",
                label: "Town",
                constant: "TOWN",
                data: "town",
                width: 1,
                height: 1,
                tiles: 1,
            },
            Entry::Sheet {
                source: "hero.png",
                label: "Hero",
                constant: "HERO",
                data: "hero",
                plan: &plan,
            },
        ];
        let mut listed: Vec<String> = symbols(ImageKind::Bg, "Town", "TOWN")
            .into_iter()
            .chain(symbols(ImageKind::Sprites, "Hero", "HERO"))
            .chain(["HeroFrame0".into(), "HeroFrame1".into()])
            .collect();
        listed.sort();
        assert_eq!(defined(&asm(&entries), &inc(&entries)), listed);
    }
}
